-- V5: operational destinations, exact world checkpoints and portable artifacts.
CREATE TABLE operational_workspaces(workspace_id TEXT PRIMARY KEY,request_id TEXT NOT NULL UNIQUE,payload_hash TEXT NOT NULL,node_id TEXT NOT NULL REFERENCES network_nodes(node_id),character_id TEXT NOT NULL,branch TEXT NOT NULL REFERENCES branches(id),kind TEXT NOT NULL CHECK(kind IN ('document','repository','pipeline')),viewer TEXT,config_json TEXT NOT NULL,checkpoint_json TEXT NOT NULL,context_json TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE workspace_transitions(transition_id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL UNIQUE REFERENCES operational_workspaces(workspace_id),state TEXT NOT NULL CHECK(state IN ('active','returned','blocked')),return_request_id TEXT UNIQUE,return_hash TEXT,receipt_json TEXT NOT NULL);
CREATE TABLE artifacts(artifact_id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,viewer TEXT,request_id TEXT NOT NULL UNIQUE,payload_hash TEXT NOT NULL,digest TEXT NOT NULL,media_type TEXT NOT NULL,size INTEGER NOT NULL,content BLOB NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE document_sources(workspace_id TEXT NOT NULL REFERENCES operational_workspaces(workspace_id),source_id TEXT NOT NULL,revision INTEGER NOT NULL,request_id TEXT NOT NULL UNIQUE,payload_hash TEXT NOT NULL,artifact_id TEXT NOT NULL REFERENCES artifacts(artifact_id),metadata_json TEXT NOT NULL,PRIMARY KEY(workspace_id,source_id,revision));
CREATE TABLE document_inquiries(inquiry_id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES operational_workspaces(workspace_id),request_id TEXT NOT NULL UNIQUE,payload_hash TEXT NOT NULL,result_json TEXT NOT NULL);
CREATE TABLE document_drafts(draft_id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES operational_workspaces(workspace_id),request_id TEXT NOT NULL UNIQUE,payload_hash TEXT NOT NULL,artifact_id TEXT NOT NULL REFERENCES artifacts(artifact_id),result_json TEXT NOT NULL);
CREATE TABLE method_transfers(transfer_id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES operational_workspaces(workspace_id),request_id TEXT NOT NULL UNIQUE,payload_hash TEXT NOT NULL,method_id TEXT NOT NULL,method_revision INTEGER NOT NULL,method_digest TEXT NOT NULL,assignment_revision INTEGER NOT NULL,assignment_digest TEXT NOT NULL,mapping_json TEXT NOT NULL,result_json TEXT NOT NULL);
CREATE TABLE transfer_trials(trial_id TEXT PRIMARY KEY,transfer_id TEXT NOT NULL REFERENCES method_transfers(transfer_id),request_id TEXT NOT NULL UNIQUE,payload_hash TEXT NOT NULL,artifact_id TEXT NOT NULL REFERENCES artifacts(artifact_id),result_json TEXT NOT NULL,sequence INTEGER NOT NULL);
CREATE TABLE transfer_check_runs(check_id TEXT PRIMARY KEY,transfer_id TEXT NOT NULL REFERENCES method_transfers(transfer_id),request_id TEXT NOT NULL UNIQUE,payload_hash TEXT NOT NULL,artifact_id TEXT NOT NULL REFERENCES artifacts(artifact_id),artifact_digest TEXT NOT NULL,report_json TEXT NOT NULL);
INSERT INTO engine_versions(component,version,compatible_engine) VALUES('workspace_interface','1','4');
